 function comboForm(id){const d=D(),menu=d.menus.find(m=>m.id===id)||d.menus.find(m=>m.combo)||d.menus.at(-1);if(!menu)throw Error('Tambahkan menu paket dulu');let chosen=menu;const m=modal('Pilihan paket combo','<form class="e-form"><label class="span2">Menu paket<select name="menuId">'+d.menus.map(x=>'<option value="'+x.id+'" '+(x.id===chosen.id?'selected':'')+'>'+esc(x.name)+' · '+money(x.price)+'</option>').join('')+'</select></label><div class="span2" id="comboGroups"></div><div class="e-form-error span2"></div><footer><button type="submit" class="primary-btn">Simpan pilihan paket</button></footer></form>');const draw=()=>{m.querySelector('#comboGroups').innerHTML=Array.from({length:6},(_,i)=>{const g=chosen.combo?.groups[i];return '<fieldset class="combo-group"><legend>Kelompok '+(i+1)+'</legend><label>Nama kelompok<input name="group'+i+'" placeholder="Contoh: Makanan / Lauk / Minuman" value="'+esc(g?.name||'')+'"></label><div class="combo-options">'+d.menus.filter(x=>x.id!==chosen.id&&!x.combo).map(x=>'<label><input type="checkbox" name="option'+i+'" value="'+x.id+'" '+(g?.options.includes(x.id)?'checked':'')+'>'+esc(x.name)+'</label>').join('')+'</div></fieldset>'}).join('')};draw();m.querySelector('[name=menuId]').onchange=e=>{chosen=d.menus.find(x=>x.id===e.target.value);draw()};m.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=e.target,btn=f.querySelector('button');btn.disabled=true;try{const values=new FormData(f),groups=Array.from({length:6},(_,i)=>({id:chosen.combo?.groups[i]?.id,name:String(values.get('group'+i)||''),options:values.getAll('option'+i)})).filter(g=>g.name.trim());await execute('combo',{menuId:chosen.id,groups});ctx.close()}catch(err){f.querySelector('.e-form-error').textContent=err.message}finally{btn.disabled=false}}}
 function receivableForm(){const d=D(),eligible=d.orders.filter(o=>!['Dibatalkan','Digabung'].includes(o.status)&&remainingFor(d,o)>0&&!d.receivables.some(r=>r.orderId===o.id));if(!eligible.length)throw Error('Buat pesanan belum lunas terlebih dahulu');const fields=[field('orderId','Pesanan / katering yang sudah dibuat','select',eligible[0].id,eligible.map(o=>[o.id,o.number+' · '+o.customer+' · '+money(remainingFor(d,o))])),field('customer','Nama pelanggan / perusahaan','text',eligible[0].customer),field('due','Jatuh tempo terakhir','date',today(),[],'required'),field('note','Catatan invoice','textarea','')];for(let i=0;i<6;i++)fields.push(field('termDue'+i,'Jatuh tempo termin '+(i+1),'date',''),field('termAmount'+i,'Nominal termin '+(i+1)+' (opsional)','number',0,[],'min="0"'));form('Invoice piutang',fields,v=>execute('receivable',{...v,terms:Array.from({length:6},(_,i)=>({due:v['termDue'+i],amount:Number(v['termAmount'+i])})).filter(t=>t.amount>0)}))}
